DECLARE @Q2 int;
SET @Cabecera=JSON_MODIFY(@Cabecera,'$.total',180); SET @Cabecera=JSON_MODIFY(@Cabecera,'$.subtotal',180);
SET @Lineas=JSON_MODIFY(@Lineas,'$[0].precioUnitario',90); SET @Lineas=JSON_MODIFY(@Lineas,'$[0].totalLinea',180);
EXEC dbo.usp_Proforma_GuardarBorrador @SP1,@DocumentoRecibido,@Importacion,@Cabecera,@Lineas,@Q2 OUTPUT;
UPDATE dbo.ProformasProveedorDetalle SET EstadoRevision='Revisada' WHERE IdProformaProveedor=@Q2;
UPDATE dbo.ProformasProveedor SET EstadoConciliacion='Conciliada' WHERE IdProformaProveedor=@Q2;
EXEC dbo.usp_Proforma_Validar @Q2;
IF NOT EXISTS(SELECT 1 FROM dbo.ProformasProveedor WHERE IdProformaProveedor=@Q2 AND VersionRespuesta=2 AND IdProformaAnterior=@Q) THROW 51901,N'Revision sin enlace',1;
IF (SELECT COUNT(*) FROM dbo.vw_OfertasValidadasVigentes WHERE IdSolicitudCotizacionProveedor=@SP1)<>1 THROW 51901,N'Duplico ofertas vigentes',1;
IF NOT EXISTS(SELECT 1 FROM dbo.vw_OfertasValidadasVigentes WHERE IdProformaProveedor=@Q2 AND PrecioPorEmpaqueDocumento=90) THROW 51901,N'No eligio revision nueva',1;
IF (SELECT PrecioUnitario FROM dbo.ProformasProveedorDetalle WHERE IdProformaProveedorDetalle=@QD)<>100 THROW 51901,N'Alteracion del original',1;

INSERT dbo.CompraAutomaticaEquivalencias(IdProveedor,CodigoProveedor,DescripcionProveedor,IdProducto,IdPresentacionProducto)
VALUES(@Proveedor,N'MISMO-CODIGO',N'Prueba',@P,@PP),(@OtroProveedor,N'MISMO-CODIGO',N'Prueba',@OtroProducto,@OtraPresentacion);
DECLARE @Encontrados TABLE(IdProducto int,IdPresentacionProducto int,NombreProducto nvarchar(150),NombrePresentacion nvarchar(150));
INSERT @Encontrados EXEC dbo.SP_CompraAutomatica_BuscarEquivalencia N'MISMO-CODIGO',N'Prueba',@Proveedor;
IF (SELECT COUNT(*) FROM @Encontrados)<>1 OR NOT EXISTS(SELECT 1 FROM @Encontrados WHERE IdProducto=@P) THROW 51901,N'Equivalencia ajena',1;
DELETE @Encontrados;
INSERT @Encontrados EXEC dbo.SP_CompraAutomatica_BuscarEquivalencia N'MISMO-CODIGO',N'Prueba',@OtroProveedor;
IF (SELECT COUNT(*) FROM @Encontrados)<>1 OR NOT EXISTS(SELECT 1 FROM @Encontrados WHERE IdProducto=@OtroProducto) THROW 51901,N'Equivalencia ajena',1;

UPDATE dbo.ProformasProveedorDetalle SET EstadoOferta='NoDisponible',Cantidad=NULL,PrecioUnitario=NULL,TotalLinea=NULL,EstadoRevision='Revisada' WHERE IdProformaProveedorDetalle=@QD;
UPDATE dbo.ProformasProveedor SET Subtotal=0,Descuento=0,IVA=0,Total=0,OtrosCargos=0,EstadoConciliacion='Conciliada' WHERE IdProformaProveedor=@Q;
EXEC dbo.usp_Proforma_Validar @Q;
IF EXISTS(SELECT 1 FROM dbo.vw_OfertasValidadasVigentes WHERE IdProformaProveedor=@Q) THROW 51901,N'Convirtio falta de oferta en precio',1;

DECLARE @M table(IdMarca int); INSERT @M EXEC dbo.usp_Marca_Insertar N'Marca temporal';
DECLARE @B table(IdProductoBase int); INSERT @B EXEC dbo.usp_ProductoBase_Insertar N'BASE-PRUEBA',N'Fertilizante prueba',N'10-30-10';
DECLARE @NuevaMarca int=(SELECT IdMarca FROM @M),@NuevaBase int=(SELECT IdProductoBase FROM @B); DECLARE @N table(IdProducto int);
INSERT @N EXEC dbo.SP_Producto_Insertar N'Fertilizante prueba',@NuevaBase,@NuevaMarca;
DECLARE @NuevoProducto int=(SELECT IdProducto FROM @N),@Kg int=(SELECT IdUnidadMedida FROM dbo.UnidadesMedida WHERE Codigo='KG');
EXEC dbo.SP_PresentacionesProducto_Insertar @NuevoProducto,N'Bolsa 2.5kg',2.5,@Kg;
IF NOT EXISTS(SELECT 1 FROM dbo.PresentacionesProducto WHERE IdProducto=@NuevoProducto AND CantidadNormalizada=2.5) THROW 51901,N'Perdio decimal',1;
EXEC dbo.usp_Marca_Actualizar @NuevaMarca,N'Marca temporal actualizada';
IF NOT EXISTS(SELECT 1 FROM dbo.Productos WHERE IdProducto=@NuevoProducto AND Marca=N'Marca temporal actualizada') THROW 51901,N'Marca no sincronizada',1;

DECLARE @NuevaSolicitud bigint=NULL,@SolicitudLineas nvarchar(max)=(SELECT 1 AS numeroLinea,@P AS idProducto,@PP AS idPresentacionProducto,0.125 AS cantidadEmpaques,CONVERT(bit,1) AS permiteAlternativas FOR JSON PATH),@Destinatarios nvarchar(max)=CONCAT(N'[',@Proveedor,N',',@OtroProveedor,N']');
 EXEC dbo.usp_Solicitud_GuardarBorrador N'SOLICITUD-API','2026-10-16',NULL,N'{"nombre":"Cliente API"}',NULL,@SolicitudLineas,@Destinatarios,@NuevaSolicitud OUTPUT;
 IF NOT EXISTS(SELECT 1 FROM dbo.SolicitudesCotizacionDetalle WHERE IdSolicitudCotizacion=@NuevaSolicitud AND CantidadEmpaquesSolicitada=0.125 AND ContenidoNormalizadoOriginal=@Normalizada) THROW 51901,N'No tomo original',1;
 EXEC dbo.usp_Solicitud_Emitir @NuevaSolicitud;
 DECLARE @Dest bigint=(SELECT MIN(IdSolicitudCotizacionProveedor) FROM dbo.SolicitudesCotizacionProveedor WHERE IdSolicitudCotizacion=@NuevaSolicitud);
 EXEC dbo.usp_Solicitud_RegistrarEnvio @Dest,@DocumentoEnviado;
 EXEC dbo.usp_Solicitud_RegistrarEnvio @Dest,@DocumentoEnviado;
 IF NOT EXISTS(SELECT 1 FROM dbo.SolicitudesCotizacionProveedor WHERE IdSolicitudCotizacionProveedor=@Dest AND Estado='Enviada' AND FechaEnvio IS NOT NULL) THROW 51901,N'No registro envio',1;

DECLARE @NuevaSolicitud bigint=NULL,@SolicitudLineas nvarchar(max)=(SELECT 1 AS numeroLinea,@P AS idProducto,@PP AS idPresentacionProducto,0.125 AS cantidadEmpaques,CONVERT(bit,1) AS permiteAlternativas FOR JSON PATH),@Destinatarios nvarchar(max)=CONCAT(N'[',@Proveedor,N',',@OtroProveedor,N']');
 EXEC dbo.usp_Solicitud_GuardarBorrador N'SOLICITUD-API','2026-10-16',NULL,N'{"nombre":"Cliente API"}',NULL,@SolicitudLineas,@Destinatarios,@NuevaSolicitud OUTPUT;
 SET @SolicitudLineas=JSON_MODIFY(@SolicitudLineas,'$[0].cantidadEmpaques',3.25);
 EXEC dbo.usp_Solicitud_GuardarBorrador N'SOLICITUD-API','2026-10-16',NULL,N'{"nombre":"Cliente API"}',N'Actualizado',@SolicitudLineas,@Destinatarios,@NuevaSolicitud OUTPUT;
 IF (SELECT COUNT(*) FROM dbo.SolicitudesCotizacionDetalle WHERE IdSolicitudCotizacion=@NuevaSolicitud)<>1 OR NOT EXISTS(SELECT 1 FROM dbo.SolicitudesCotizacionDetalle WHERE IdSolicitudCotizacion=@NuevaSolicitud AND CantidadEmpaquesSolicitada=3.25) THROW 51901,N'Borrador duplicado',1;

DECLARE @NuevaSolicitud bigint; EXEC dbo.usp_Solicitud_CrearRevision @S1,@NuevaSolicitud OUTPUT;
 IF NOT EXISTS(SELECT 1 FROM dbo.SolicitudesCotizacion WHERE IdSolicitudCotizacion=@NuevaSolicitud AND VersionSolicitud=2 AND Estado='Borrador' AND IdSolicitudAnterior=@S1) THROW 51901,N'Revision invalida',1;
 IF EXISTS(SELECT 1 FROM dbo.SolicitudesCotizacionProveedor WHERE IdSolicitudCotizacion=@NuevaSolicitud AND IdDocumentoEnviado IS NOT NULL) THROW 51901,N'Copio envio anterior',1;

DECLARE @Id bigint,@I bigint,@Hash varbinary(max)=HASHBYTES('SHA2_256',N'API-PDF'); EXEC dbo.usp_Documento_Registrar N'api.pdf',N'pruebas-rollback/api.pdf',@Hash,512,'Recibido',NULL,@Id OUTPUT;
 EXEC dbo.usp_Importacion_Registrar @Id,N'lector-v1','Manual','Parcial',N'{"original":"sin alterar"}',N'[]',@I OUTPUT;
 IF NOT EXISTS(SELECT 1 FROM dbo.ImportacionesDocumento WHERE IdImportacionDocumento=@I AND DatosExtraidosJson=N'{"original":"sin alterar"}') THROW 51901,N'Datos extraidos perdidos',1;

DECLARE @L nvarchar(max)=JSON_QUERY(@Lineas,'$[0]'); SET @L=JSON_MODIFY(@L,'$.precioUnitario',105); SET @L=JSON_MODIFY(@L,'$.totalLinea',210);
 EXEC dbo.usp_Proforma_ActualizarLinea @QD,@L,N'Corregir lectura PDF';
 IF NOT EXISTS(SELECT 1 FROM dbo.ProformasProveedorDetalle WHERE IdProformaProveedorDetalle=@QD AND PrecioUnitario=105 AND EstadoRevision='Pendiente' AND SePuedeRegistrar=0) THROW 51901,N'No reinicio revision',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.ProformasProveedor WHERE IdProformaProveedor=@Q AND EstadoConciliacion='Pendiente' AND IdDocumentoOrigen=@DocumentoRecibido) THROW 51901,N'No reinicio conciliacion',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.CambiosCotizacion WHERE IdProformaProveedorDetalle=@QD AND Motivo=N'Corregir lectura PDF' AND JSON_VALUE(CambiosJson,'$.antes.PrecioUnitario') IS NOT NULL) THROW 51901,N'Falta motivo historico',1;

DECLARE @Revision int; EXEC dbo.usp_Proforma_CrearRevision @Q,@Revision OUTPUT;
 IF NOT EXISTS(SELECT 1 FROM dbo.ProformasProveedor WHERE IdProformaProveedor=@Revision AND VersionRespuesta=2 AND Estado='Borrador' AND EstadoConciliacion='Pendiente' AND IdDocumentoOrigen=@DocumentoRecibido) THROW 51901,N'Revision incorrecta',1;
 IF EXISTS(SELECT 1 FROM dbo.ProformasProveedorDetalle WHERE IdProformaProveedor=@Revision AND EstadoRevision<>'Pendiente') THROW 51901,N'Revision heredada sin revisar',1;

