 INSERT @C EXEC dbo.usp_Cotizaciones_CompararSolicitud @S1,'CRC','Bruto','2026-10-16';
IF NOT EXISTS(SELECT 1 FROM @C WHERE EsComparable=1 AND ABS(PrecioPorUnidadBase-100/@Normalizada)<0.000001 AND DescuentoGlobalDocumento=20 AND IVADocumento=10 AND OtrosCargosDocumento=5) THROW 51901,N'Prorrateo o precio incorrecto',1;

