DECLARE @ImputacionDoc nvarchar(max)=(SELECT N'Entrega a finca Norte' AS motivo,
 JSON_QUERY((SELECT @PartidaNorte AS idPartidaPresupuesto,100 AS monto FOR JSON PATH)) AS distribucion FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
DECLARE @LineasDoc nvarchar(max)=(SELECT l.idProducto,l.idPresentacionProducto,l.cantidadComprada,l.precioTotal,JSON_QUERY(l.imputacionPresupuesto) AS imputacionPresupuesto FROM
 (SELECT @P AS idProducto,@PP AS idPresentacionProducto,2 AS cantidadComprada,100 AS precioTotal,JSON_QUERY(@ImputacionDoc) AS imputacionPresupuesto
 UNION ALL SELECT @OtroProducto,@OtraPresentacion,3,150,NULL) l FOR JSON PATH);
DECLARE @OpDoc uniqueidentifier=NEWID(),@CabDoc bigint;
EXEC dbo.usp_Compra_RegistrarDocumento @Proveedor,'20261016',N'CRC',@LineasDoc,@OpDoc;
SELECT @CabDoc=IdCompraCabecera FROM dbo.ComprasCabecera WHERE IdOperacion=@OpDoc;
IF NOT EXISTS(SELECT 1 FROM dbo.vw_SaldosPresupuesto WHERE IdPartidaPresupuesto=@PartidaNorte AND Ejecutado=100)
 OR (SELECT COUNT(*) FROM dbo.Compras WHERE IdCompraCabecera=@CabDoc)<>2 THROW 51901,N'No imputó por producto',1;
EXEC dbo.usp_Compra_RegistrarDocumento @Proveedor,'20261016',N'CRC',@LineasDoc,@OpDoc;
IF (SELECT SUM(CambioEjecutado) FROM dbo.MovimientosPresupuesto WHERE IdPartidaPresupuesto=@PartidaNorte)<>100
 THROW 51901,N'Duplicó la ejecución del presupuesto',1;

DECLARE @BorradorEd bigint,@OpCrearEd uniqueidentifier=NEWID(),@OpEditarEd uniqueidentifier=NEWID();
DECLARE @VersionEd uniqueidentifier,@PartidaEd bigint,@PartidasEd nvarchar(max)=(SELECT @Rubro AS idRubroPresupuesto,100 AS monto FOR JSON PATH);
EXEC dbo.usp_Presupuesto_Crear N'Borrador a corregir','20270101','20271231',N'CRC',@PartidasEd,@OpCrearEd,N'Plan inicial',@BorradorEd OUTPUT,@FincaNorte;
SET @VersionEd=@OpCrearEd;
SELECT @PartidaEd=IdPartidaPresupuesto FROM dbo.PartidasPresupuesto WHERE IdPresupuesto=@BorradorEd;

SET @PartidasEd=(SELECT @Rubro AS idRubroPresupuesto,125.0001 AS monto FOR JSON PATH);
EXEC dbo.usp_Presupuesto_EditarBorrador @BorradorEd,@VersionEd,N'Plan final','20270201','20271130',N'USD',@PartidasEd,@OpEditarEd,@FincaSur;
IF NOT EXISTS(SELECT 1 FROM dbo.Presupuestos WHERE IdPresupuesto=@BorradorEd AND Nombre=N'Plan final' AND Moneda='USD'
 AND IdFinca=@FincaSur AND FechaInicio='20270201' AND IdOperacionCreacion=@OpCrearEd AND IdOperacionEdicion=@OpEditarEd)
 THROW 51901,N'No conservó o corrigió la cabecera',1;
IF NOT EXISTS(SELECT 1 FROM dbo.PartidasPresupuesto WHERE IdPartidaPresupuesto=@PartidaEd AND MontoInicial=125.0001)
 OR EXISTS(SELECT 1 FROM dbo.MovimientosPresupuesto WHERE IdPartidaPresupuesto=@PartidaEd) THROW 51901,N'El borrador registró gasto o cambió la partida',1;
DECLARE @AprobarEd uniqueidentifier=NEWID();
EXEC dbo.usp_Presupuesto_Aprobar @BorradorEd,@AprobarEd,N'Aprobar plan corregido';
IF NOT EXISTS(SELECT 1 FROM dbo.vw_SaldosPresupuesto WHERE IdPartidaPresupuesto=@PartidaEd AND Aprobado=125.0001 AND Disponible=125.0001)
 THROW 51901,N'No aprobó el monto corregido',1;

